1187                      } else {
1188                          LOG.warn("Failed to parse theme from line: [" + line + "].");
1189                      }
1190                  }
1191              } catch (IOException x) {
1192                  LOG.error("Failed to resolve list of themes.", x);
1193                  themes.add(new Theme("default", "Airsonic default"));
1194              }
1195          }
1196          return themes.toArray(new Theme[themes.size()]);
1197      }
