 34  /**
 35   * Subclass of {@link InputStream} which provides on-the-fly transcoding.
 36   * Instances of <code>TranscodeInputStream</code> can be chained together, for instance to convert
 37   * from OGG to WAV to MP3.
 38   *
 39   * @author Sindre Mehus
 40   */
 41  public class TranscodeInputStream extends InputStream {
 42  
 43      private static final Logger LOG = LoggerFactory.getLogger(TranscodeInputStream.class);
 44  
 45      private InputStream processInputStream;
 46      private OutputStream processOutputStream;
 47      private Process process;
 48      private final Path tmpFile;
 49  
 50      /**
 51       * Creates a transcoded input stream by executing an external process. If <code>in</code> is not null,
 52       * data from it is copied to the command.
 53       *
 54       * @param processBuilder Used to create the external process.
 55       * @param in Data to feed to the process.  May be {@code null}.
 56       * @param tmpFile Temporary file to delete when this stream is closed.  May be {@code null}.
 57       * @throws IOException If an I/O error occurs.
 58       */
 59      public TranscodeInputStream(ProcessBuilder processBuilder, final InputStream in, Path tmpFile) throws IOException {
 60          this.tmpFile = tmpFile;
 61          LOG.info("Starting transcoder: {}", processBuilder.command().stream().collect(Collectors.joining("][", "[", "]")));
 62  
 63          process = processBuilder.start();
 64          processOutputStream = process.getOutputStream();
 65          processInputStream = process.getInputStream();
 66  
 67          // Must read stderr from the process, otherwise it may block.
 68          final String name = processBuilder.command().get(0);
 69          new InputStreamReaderThread(process.getErrorStream(), name, true).start();
 70  
 71          // Copy data in a separate thread
 72          if (in != null) {
 73              new Thread(name + " TranscodedInputStream copy thread") {
 74                  @Override
 75                  public void run() {
 76                      try {
 77                          IOUtils.copy(in, processOutputStream);
 78                      } catch (IOException x) {
 79                          // Intentionally ignored. Will happen if the remote player closes the stream.
 80                      } finally {
 81                          FileUtil.closeQuietly(in);
 82                          FileUtil.closeQuietly(processOutputStream);
 83                      }
 84                  }
 85              }.start();
 86          }
 87      }
