114      @PostMapping
115      protected ModelAndView handleRequestInternal(HttpServletRequest request, HttpServletResponse response) {
116  
117          Map<String, Object> map = new HashMap<>();
118          List<Path> uploadedFiles = new ArrayList<>();
119          List<Path> unzippedFiles = new ArrayList<>();
120          List<Exception> exceptions = new ArrayList<>();
121          User user = securityService.getCurrentUser(request);
122          TransferStatus status = null;
123          UUID callback = null;
124          Path dir = null;
125  
126          try {
127  
128              status = statusService.createUploadStatus(playerService.getPlayer(request, response, false, false));
129              status.setBytesTotal(request.getContentLength());
130              brokerTemplate.convertAndSendToUser(status.getPlayer().getUsername(), "/queue/uploads/status",
131                      new UploadInfo(status.getId(), 0L, status.getBytesTotal()));
132  
133              // Check that we have a file upload request
134              if (!ServletFileUpload.isMultipartContent(request)) {
135                  throw new Exception("Illegal request.");
136              }
137  
138              boolean unzip = false;
139  
140              UploadListener listener = new UploadListenerImpl(status, settingsService.getUploadBitrateLimiter(), brokerTemplate);
141  
142              FileItemFactory factory = new MonitoredDiskFileItemFactory(listener);
143              ServletFileUpload upload = new ServletFileUpload(factory);
144  
145              List<?> items = upload.parseRequest(request);
146  
147              // First, look for "dir" and "unzip" parameters.
148              for (Object o : items) {
149                  FileItem item = (FileItem) o;
150  
151                  if (item.isFormField() && "dir".equals(item.getFieldName())) {
152                      dir = Paths.get(item.getString());
153                  } else if (item.isFormField() && "unzip".equals(item.getFieldName())) {
154                      unzip = true;
155                  } else if (item.isFormField() && "callback".equals(item.getFieldName())) {
156                      callback = UUID.fromString(item.getString());
157                  }
158              }
159  
160              if (dir == null) {
161                  throw new Exception("Missing 'dir' parameter.");
162              }
163  
164              checkUploadAllowed(user, dir, false);
165  
166              if (!Files.exists(dir)) {
167                  Files.createDirectories(dir);
168              }
169  
170              // Look for file items.
171              for (Object o : items) {
172                  FileItem item = (FileItem) o;
173  
174                  if (!item.isFormField()) {
175                      String fileName = item.getName();
176                      if (!fileName.trim().isEmpty()) {
177  
178                          Path targetFile = dir.resolve(Paths.get(fileName).getFileName());
179  
180                          try {
181                              checkUploadAllowed(user, targetFile, true);
182                          } catch (IOException e) {
183                              exceptions.add(e);
184                              continue;
185                          }
186  
187                          item.write(targetFile.toFile());
188                          uploadedFiles.add(targetFile);
189                          LOG.info("Uploaded {} ", targetFile);
190  
191                          if (unzip && SUPPORTED_ZIP_FORMATS.contains(MoreFiles.getFileExtension(targetFile).toLowerCase())) {
192                              unzip(targetFile, unzippedFiles, exceptions);
193                          }
194                      }
195                  }
196              }
197          } catch (Exception x) {
198              LOG.warn("Uploading failed.", x);
199              exceptions.add(x);
200          } finally {
201              if (status != null) {
202                  statusService.removeUploadStatus(status);
203                  brokerTemplate.convertAndSendToUser(status.getPlayer().getUsername(), "/queue/uploads/status",
204                          new UploadInfo(status.getId(), status.getBytesTotal() + 1, status.getBytesTotal()));
205                  securityService.updateUserByteCounts(user, 0L, 0L, status.getBytesTransferred());
206              }
207              if (callback != null && dir != null) {
208                  try {
209                      registeredCallbacks.getOrDefault(callback, p -> {}).accept(dir);
210                  } catch (Exception e) {
211                      LOG.warn("Callback failed", e);
212                      exceptions.add(e);
213                  }
214              }
215          }
216  
217          map.put("exceptions", exceptions);
218          map.put("uploadedFiles", uploadedFiles);
219          map.put("unzippedFiles", unzippedFiles);
220  
221          return new ModelAndView("upload", "model", map);
222      }
