353      private void copyEntry(Path file, ArchiveEntry entry, LambdaUtils.ThrowingConsumer<Path, IOException> copier,
354              List<Path> unzippedFiles, List<Exception> exceptions) {
355          final Path toPath = file.resolveSibling(entry.getName());
356          try {
357              if (!toPath.normalize().startsWith(file.getParent())) {
358                  throw new IOException("Bad zip filename: " + toPath.toString());
359              }
360              if (entry.isDirectory()) {
361                  Files.createDirectories(toPath);
362              } else {
363                  Path parent = toPath.getParent();
364                  Files.createDirectories(parent);
365                  if (!Files.isDirectory(parent)) {
366                      throw new IOException("Failed to create directory: " + parent);
367                  }
368  
369                  copier.accept(toPath);
370                  unzippedFiles.add(toPath);
371                  LOG.debug("Unzipped {}", toPath);
372  
373              }
374          } catch (IOException e) {
375              exceptions.add(e);
376              LOG.debug("Could not unzip {}", toPath, e);
377          }
378  
379          LOG.info("Processed {}", toPath);
380      }
