389          private volatile int lastBroadcastPercentage = 0;
390  
391          private UploadListenerImpl(TransferStatus status, RateLimiter rateLimiter,
392                  SimpMessagingTemplate brokerTemplate) {
393              this.status = status;
394              this.brokerTemplate = brokerTemplate;
395              this.rateLimiter = rateLimiter;
396          }
397  
398          @Override
399          public void start(String fileName) {
400              status.setExternalFile(Paths.get(fileName));
401          }
402  
403          @Override
404          public void bytesRead(long bytesRead) {
405              status.addBytesTransferred(bytesRead);
406              broadcast();
407              // Throttle bitrate.
408              rateLimiter.acquire((int) bytesRead);
409          }
410  
411          private void broadcast() {
412              long percentDone = 100 * status.getBytesTransferred() / Math.max(1, status.getBytesTotal());
413              // broadcast every 2% (no need to broadcast at every byte read)
414              if (percentDone - lastBroadcastPercentage > 2) {
415                  lastBroadcastPercentage = (int) percentDone;
416                  CompletableFuture.runAsync(() -> brokerTemplate.convertAndSendToUser(
417                          status.getPlayer().getUsername(),
418                          "/queue/uploads/status",
419                          new UploadInfo(status.getId(), status.getBytesTransferred(), status.getBytesTotal())));
420              }
421          }
422      }
423  
424  }

