116      @Transactional(isolation = Isolation.READ_COMMITTED)
117      public void reassignChildren(MusicFolder from, MusicFolder to) {
118          if (to.getPath().getNameCount() > from.getPath().getNameCount()) {
119              // assign ancestor -> descendant
120              MusicFolder ancestor = from;
121              MusicFolder descendant = to;
122              String relativePath = ancestor.getPath().relativize(descendant.getPath()).toString();
123              // update children
124              int len = relativePath.length();
125              String sql = "update media_file set "
126                      + "folder_id=?, "
127                      + "path=SUBSTR(path, " + (len + 2) + "), "
128                      + "parent_path=(case "
129                      + "  when (length(parent_path) > " + len + ") then SUBSTR(parent_path, " + (len + 2) + ") "
130                      + "  else SUBSTR(parent_path, " + (len + 1) + ") end) "
131                      + "where folder_id=? and path like ?";
132              update(sql, descendant.getId(), ancestor.getId(), relativePath + File.separator + "%");
133              sql = "update cover_art set "
134                      + "folder_id=?, "
135                      + "path=SUBSTR(path, " + (len + 2) + ") "
136                      + "where folder_id=? and path like ?";
137              update(sql, descendant.getId(), ancestor.getId(), relativePath + File.separator + "%");
138  
139              // update root
140              sql = "update media_file set "
141                      + "folder_id=?, "
142                      + "path='', "
143                      + "parent_path=null, "
144                      + "title=?, "
145                      + "type=? "
146                      + "where folder_id=? and path=?";
147              update(sql, descendant.getId(), descendant.getName(), MediaFile.MediaType.DIRECTORY, ancestor.getId(), relativePath);
148          } else {
149              // assign descendant -> ancestor
150              MusicFolder ancestor = to;
151              MusicFolder descendant = from;
152              Path relativePath = ancestor.getPath().relativize(descendant.getPath());
153              // update root
154              String sql = "update media_file set "
155                      + "folder_id=?, "
156                      + "title=null, "
157                      + "path=?, "
158                      + "parent_path=? "
159                      + "where folder_id=? and path=''";
160              update(sql, ancestor.getId(), relativePath, relativePath.getParent() == null ? "" : relativePath.getParent().toString(), descendant.getId());
161              // update children
162              sql = "update media_file set "
163                      + "folder_id=?, "
164                      + "path=concat(?, path), "
165                      + "parent_path=(case"
166                      + "  when (parent_path = '') then ?"
167                      + "  else concat(?, parent_path) end) "
168                      + "where folder_id=?";
169              update(sql, ancestor.getId(), relativePath + File.separator, relativePath, relativePath + File.separator, descendant.getId());
170              sql = "update cover_art set folder_id=?, path=concat(?, path) where folder_id=?";
171              update(sql, ancestor.getId(), relativePath + File.separator, descendant.getId());
172          }
173      }
