179      /**
180       * Scans the media library.
181       * The scanning is done asynchronously, i.e., this method returns immediately.
182       */
183      public synchronized void scanLibrary() {
184          if (isScanning()) {
185              return;
186          }
187          setScanning(true);
188  
189          ForkJoinPool pool = new ForkJoinPool(scannerParallelism, mediaScannerThreadFactory, null, true);
190  
191          CompletableFuture.runAsync(() -> doScanLibrary(pool), pool)
192                  .thenRunAsync(() -> playlistService.importPlaylists(), pool)
193                  .whenComplete((r,e) -> pool.shutdown())
194                  .whenComplete((r,e) -> setScanning(false));
195      }
