197      private void doScanLibrary(ForkJoinPool pool) {
198          LOG.info("Starting to scan media library.");
199          MediaLibraryStatistics statistics = new MediaLibraryStatistics();
200          LOG.debug("New last scan date is {}", statistics.getScanDate());
201  
202          try {
203              // Maps from artist name to album count.
204              Map<String, AtomicInteger> albumCount = new ConcurrentHashMap<>();
205              Map<String, Artist> artists = new ConcurrentHashMap<>();
206              Map<String, Album> albums = new ConcurrentHashMap<>();
207              Map<Integer, Album> albumsInDb = new ConcurrentHashMap<>();
208              Map<Integer, Set<String>> encountered = new ConcurrentHashMap<>();
209              Genres genres = new Genres();
210  
211              scanCount.set(0);
212  
213              mediaFileService.setMemoryCacheEnabled(false);
214              indexManager.startIndexing();
215  
216              // Recurse through all files on disk.
217              mediaFolderService.getAllMusicFolders()
218                  .parallelStream()
219                      .forEach(musicFolder -> scanFile(mediaFileService.getMediaFile(Paths.get(""), musicFolder, false),
220                              musicFolder, statistics, albumCount, artists, albums, albumsInDb, genres, encountered));
221  
222              LOG.info("Scanned media library with {} entries.", scanCount.get());
223  
224              // Update statistics
225              statistics.incrementArtists(albumCount.size());
226              statistics.incrementAlbums(albumCount.values().parallelStream().mapToInt(x -> x.get()).sum());
227  
228              LOG.info("Persisting albums");
229              CompletableFuture<Void> albumPersistence = CompletableFuture
230                      .allOf(albums.values().parallelStream()
231                              .distinct()
232                              .map(a -> CompletableFuture.supplyAsync(() -> {
233                                  albumDao.createOrUpdateAlbum(a);
234                                  return a;
235                              }, pool).thenAcceptAsync(coverArtService::persistIfNeeded))
236                              .toArray(CompletableFuture[]::new))
237                      .thenRunAsync(() -> {
238                          LOG.info("Marking non-present albums.");
239                          albumDao.markNonPresent(statistics.getScanDate());
240                      }, pool)
241                      .thenRunAsync(() -> LOG.info("Album persistence complete"), pool);
242  
243              LOG.info("Persisting artists");
244              CompletableFuture<Void> artistPersistence = CompletableFuture
245                      .allOf(artists.values().parallelStream()
246                              .map(a -> CompletableFuture.supplyAsync(() -> {
247                                  artistDao.createOrUpdateArtist(a);
248                                  return a;
249                              }, pool).thenAcceptAsync(coverArtService::persistIfNeeded))
250                              .toArray(CompletableFuture[]::new))
251                      .thenRunAsync(() -> {
252                          LOG.info("Marking non-present artists.");
253                          artistDao.markNonPresent(statistics.getScanDate());
254                      }, pool)
255                      .thenRunAsync(() -> LOG.info("Artist persistence complete"), pool);
256  
257              LOG.info("Marking present files");
258              CompletableFuture<Void> mediaFilePersistence = CompletableFuture
259                      .runAsync(() -> mediaFileDao.markPresent(encountered, statistics.getScanDate()), pool)
260                      .thenRunAsync(() -> {
261                          LOG.info("Marking non-present files.");
262                          mediaFileDao.markNonPresent(statistics.getScanDate());
263                      }, pool)
264                      .thenRunAsync(() -> LOG.info("File marking complete"), pool);
265  
266              LOG.info("Persisting genres");
267              CompletableFuture<Void> genrePersistence = CompletableFuture
268                      .runAsync(() -> {
269                          LOG.info("Updating genres");
270                          boolean genresSuccessful = mediaFileDao.updateGenres(genres.getGenres());
271                          LOG.info("Genre persistence successfully complete: {}", genresSuccessful);
272                      }, pool);
273  
274              CompletableFuture.allOf(albumPersistence, artistPersistence, mediaFilePersistence, genrePersistence).join();
275  
276              if (settingsService.getClearFullScanSettingAfterScan()) {
277                  settingsService.setClearFullScanSettingAfterScan(null);
278                  settingsService.setFullScan(null);
279                  settingsService.save();
280              }
281  
282              LOG.info("Completed media library scan.");
283  
284          } catch (Throwable x) {
285              LOG.error("Failed to scan media library.", x);
286          } finally {
287              mediaFileService.setMemoryCacheEnabled(true);
288              indexManager.stopIndexing(statistics);
289              LOG.info("Media library scan took {}s", ChronoUnit.SECONDS.between(statistics.getScanDate(), Instant.now()));
290          }
291      }
