293      private void scanFile(MediaFile file, MusicFolder musicFolder, MediaLibraryStatistics statistics,
294              Map<String, AtomicInteger> albumCount, Map<String, Artist> artists, Map<String, Album> albums,
295              Map<Integer, Album> albumsInDb, Genres genres, Map<Integer, Set<String>> encountered) {
296          if (scanCount.incrementAndGet() % 250 == 0) {
297              broadcastScanStatus();
298              LOG.info("Scanned media library with {} entries.", scanCount.get());
299          }
300  
301          LOG.trace("Scanning file {} in folder {} ({})", file.getPath(), musicFolder.getId(), musicFolder.getName());
302  
303          // Update the root folder if it has changed
304          if (!musicFolder.getId().equals(file.getFolderId())) {
305              file.setFolderId(musicFolder.getId());
306              mediaFileService.updateMediaFile(file);
307          }
308  
309          indexManager.index(file, musicFolder);
310  
311          if (file.isDirectory()) {
312              mediaFileService.getChildrenOf(file, true, true, false, false).parallelStream()
313                      .forEach(child -> scanFile(child, musicFolder, statistics, albumCount, artists, albums, albumsInDb, genres, encountered));
314          } else {
