202      private String createSortableName(String name, String[] ignoredArticles) {
203          String uppercaseName = name.toUpperCase();
204          for (String article : ignoredArticles) {
205              if (uppercaseName.startsWith(article.toUpperCase() + " ")) {
206                  return name.substring(article.length() + 1) + ", " + article;
207              }
208          }
209          return name;
210      }
