212      /**
213       * Returns the music index to which the given artist belongs.
214       *
215       * @param artist  The artist in question.
216       * @param indexes List of available indexes.
217       * @return The music index to which this music file belongs, or {@link MusicIndex#OTHER} if no index applies.
218       */
219      private MusicIndex getIndex(SortableArtist artist, List<MusicIndex> indexes) {
220          String sortableName = artist.getSortableName().toUpperCase();
221          for (MusicIndex index : indexes) {
222              for (String prefix : index.getPrefixes()) {
223                  if (sortableName.startsWith(prefix.toUpperCase())) {
224                      return index;
225                  }
226              }
227          }
228          return MusicIndex.OTHER;
229      }
