239      private static class MusicIndexComparator implements Comparator<MusicIndex>, Serializable {
240  
241          private List<MusicIndex> indexes;
242  
243          public MusicIndexComparator(List<MusicIndex> indexes) {
244              this.indexes = indexes;
245          }
246  
247          @Override
248          public int compare(MusicIndex a, MusicIndex b) {
249              int indexA = indexes.indexOf(a);
250              int indexB = indexes.indexOf(b);
251  
252              if (indexA == -1) {
253                  indexA = Integer.MAX_VALUE;
254              }
255              if (indexB == -1) {
256                  indexB = Integer.MAX_VALUE;
257              }
258  
259              return Integer.compare(indexA, indexB);
260          }
261      }
