237      @CacheEvict(cacheNames = "playlistCache", key = "#playlist.id")
238      public void updatePlaylist(Playlist playlist, boolean filesChangedBroadcastContext) {
239          Playlist oldPlaylist = getPlaylist(playlist.getId());
240          playlistDao.updatePlaylist(playlist);
241          runAsync(() -> {
242              BroadcastedPlaylist bp = new BroadcastedPlaylist(playlist, filesChangedBroadcastContext);
243              if (playlist.getShared()) {
244                  brokerTemplate.convertAndSend("/topic/playlists/updated", bp);
245              } else {
246                  if (oldPlaylist.getShared()) {
247                      brokerTemplate.convertAndSend("/topic/playlists/deleted", playlist.getId());
248                  }
249                  Stream.concat(Stream.of(playlist.getUsername()), getPlaylistUsers(playlist.getId()).stream())
250                          .forEach(u -> brokerTemplate.convertAndSendToUser(u, "/queue/playlists/updated", bp));
251              }
252          });
253      }
