299      public void importPlaylists() {
300          try {
301              LOG.info("Starting playlist import.");
302              doImportPlaylists();
303              LOG.info("Completed playlist import.");
304          } catch (Throwable x) {
305              LOG.warn("Failed to import playlists: " + x, x);
306          }
307      }
308  
309      private void doImportPlaylists() {
310          String playlistFolderPath = settingsService.getPlaylistFolder();
311          if (playlistFolderPath == null) {
312              return;
313          }
314          Path playlistFolder = Paths.get(playlistFolderPath);
315          if (!Files.exists(playlistFolder)) {
316              return;
317          }
318  
319          List<Playlist> allPlaylists = playlistDao.getAllPlaylists();
320          try (Stream<Path> children = Files.walk(playlistFolder)) {
321              children.forEach(f -> importPlaylist(f, allPlaylists));
322          } catch (IOException ex) {
323              LOG.warn("Error while reading directory {} when importing playlists", playlistFolder, ex);
324          }
325      }
326  
327      private void importPlaylist(Path f, List<Playlist> allPlaylists) {
328          if (Files.isRegularFile(f) && Files.isReadable(f)) {
329              try {
330                  importPlaylistIfUpdated(f, allPlaylists.stream().filter(p -> f.getFileName().toString().equals(p.getImportedFrom())).findAny().orElse(null));
331              } catch (Exception x) {
332                  LOG.warn("Failed to auto-import playlist {}", f, x);
333              }
334          }
335      }
336  
337      public Playlist importPlaylist(String username, String playlistName, String fileName, Path file, InputStream inputStream, Playlist existingPlaylist) throws Exception {
338  
339          // TODO: handle other encodings
340          final SpecificPlaylist inputSpecificPlaylist = SpecificPlaylistFactory.getInstance().readFrom(inputStream, "UTF-8");
341          if (inputSpecificPlaylist == null) {
342              throw new Exception("Unsupported playlist " + fileName);
343          }
344          PlaylistImportHandler importHandler = getImportHandler(inputSpecificPlaylist);
345          LOG.debug("Using {} playlist import handler", importHandler.getClass().getSimpleName());
346  
347          Pair<List<MediaFile>, List<String>> result = importHandler.handle(inputSpecificPlaylist, file);
348  
349          if (result.getLeft().isEmpty() && !result.getRight().isEmpty()) {
350              throw new Exception("No songs in the playlist were found.");
351          }
352  
353          for (String error : result.getRight()) {
354              LOG.warn("File in playlist '{}' not found: {}", fileName, error);
355          }
356          Instant now = Instant.now();
357          Playlist playlist;
358          if (existingPlaylist == null) {
359              playlist = new Playlist();
360              playlist.setUsername(username);
361              playlist.setCreated(now);
362              playlist.setChanged(now);
363              playlist.setShared(true);
364              playlist.setName(playlistName);
365              playlist.setComment("Auto-imported from " + fileName);
366              playlist.setImportedFrom(fileName);
367              createPlaylist(playlist);
368          } else {
369              playlist = existingPlaylist;
370          }
371  
372          setFilesInPlaylist(playlist.getId(), result.getLeft());
373  
374          return playlist;
375      }
376  
377      private void importPlaylistIfUpdated(Path file, Playlist existingPlaylist) throws Exception {
378          String fileName = file.getFileName().toString();
379          if (existingPlaylist != null && Files.getLastModifiedTime(file).toMillis() <= existingPlaylist.getChanged().toEpochMilli()) {
380              // Already imported and not changed since.
381              return;
382          }
383  
384          try (InputStream in = Files.newInputStream(file)) {
385              importPlaylist(User.USERNAME_ADMIN, FilenameUtils.getBaseName(fileName), fileName, null, in, existingPlaylist);
386              LOG.info("Auto-imported playlist {}", file);
387          }
388      }
