 49      /**
 50       * Check if a HSQLDB database upgrade will occur and backups are needed.
 51       *
 52       * DB   Driver      Likely reason                                Decision
 53       * null -           new db or non-legacy                         false
 54       * -    null or !2  something went wrong, we better make copies  true
 55       * 1.x  2.x         this is the big upgrade                      true
 56       * 2.x  2.x         already up to date                           false
 57       *
 58       * all else true (default)
 59       *
 60       * @return true if a database backup/migration should be performed
 61       */
 62      public static boolean isHsqlDbBackupNeeded(String dbPath, String jdbcUrl) {
 63          // Check the current database version
 64          String currentVersion = getHsqlDbVersion(dbPath);
 65          if (currentVersion == null) {
 66              LOG.debug("HSQLDB database not found, won't back up");
 67              return false;
 68          }
 69  
 70          try {
 71              // as we're running before spring's datasource initialises... we need to try loading the driver ourselves
 72              EmbeddedDatabaseConnection conn = EmbeddedDatabaseConnection.get(null);
 73              if (conn != null) {
 74                  Class.forName(conn.getDriverClassName());
 75              }
 76          } catch (ClassNotFoundException e) {
 77              throw new RuntimeException("Unable to load HSQLDB driver", e);
 78          }
 79  
 80          // Sanity check the database driver version (better be 2.x)
 81          String driverVersion = null;
 82          try {
 83              Driver driver = DriverManager.getDriver(jdbcUrl);
 84              driverVersion = String.format("%d.%d", driver.getMajorVersion(), driver.getMinorVersion());
 85              if (driver.getMajorVersion() != 2) {
 86                  LOG.warn("HSQLDB database driver version {} is untested. Will make a copy of the DB prior to connecting. This may upgrade the database from version {}", driverVersion, currentVersion);
 87                  return true;
 88              }
 89          } catch (SQLException e) {
 90              LOG.warn("HSQLDB database driver version cannot be determined. Will make a copy of the DB prior to connecting. This may upgrade the database from version {}", currentVersion, e);
 91              return true;
 92          }
 93  
 94          if (currentVersion.startsWith("2.")) {
 95              // If the database version is 2.x, it matches the driver major version, the upgrade should be relatively painless.
 96              LOG.debug("HSQLDB database backup not required for driver version {} connecting (and if needed, upgrading) DB version {}", currentVersion, driverVersion);
 97              return false;
 98          } else if (currentVersion.startsWith("1.")) {
 99              // If we're on a 1.x database, we're upgrading to 2.x and need to back up files.
100              LOG.info("HSQLDB database upgrade needed, from version {} to {}", currentVersion, driverVersion);
101              return true;
102          } else {
103              // If this happens we're on a completely untested version and we don't know what will happen.
104              LOG.warn("HSQLDB database upgrade needed, from version {} to {}", currentVersion, driverVersion);
105              return true;
106          }
107      }
