113      public static Path performHsqlDbBackup(String dbPath) throws IOException {
114          String timestamp = DateTimeFormatter.ofPattern("yyyyMMddHHmmss").format(LocalDateTime.now());
115          Path source = Paths.get(dbPath).getParent();
116          Path destination = source.resolveSibling("backups").resolve(String.format("%s.backup.%s", source.getFileName().toString(), timestamp));
117  
118          LOG.debug("Performing HSQLDB database backup...");
119          FileUtils.copyDirectory(source.toFile(), destination.toFile());
120          LOG.info("HSQLDB database backed up to {}", destination.toString());
121  
122          return destination;
123      }
