125      /**
126       * Perform an in-place database upgrade from HSQLDB 1.x to 2.x.
127       */
128      public static void performHsqlDbUpgrade(String url, String user, String password) throws SQLException {
129          LOG.debug("Performing HSQLDB database upgrade...");
130  
131          // This will upgrade HSQLDB on the first connection. This does not
132          // use Spring's DataSource, as running SHUTDOWN against it will
133          // prevent further connections to the database.
134          try (Connection conn = getHsqlDbConnection(url, user, password)) {
135              LOG.debug("Database connection established. Current version is: {}", conn.getMetaData().getDatabaseProductVersion());
136              // On upgrade, the official documentation recommends that we
137              // run 'SHUTDOWN SCRIPT' to compact all the database into a
138              // single SQL file.
139              //
140              // In practice, if we don't do that, we did not observe issues
141              // immediately but after the upgrade.
142              LOG.debug("Shutting down database (SHUTDOWN SCRIPT)...");
143              try (Statement st = conn.createStatement()) {
144                  st.execute("SHUTDOWN SCRIPT");
145              }
146          }
147  
148          LOG.info("HSQLDB database has been upgraded");
149      }
