 71      private static URI calculateProxyUri(HttpServletRequest request) throws URISyntaxException {
 72          String xForwardedHost = request.getHeader(X_FORWARDED_HOST);
 73          // If the request has been through multiple reverse proxies,
 74          // We need to return the original Host that the client used
 75          if (xForwardedHost != null) {
 76              xForwardedHost = xForwardedHost.split(",")[0];
 77          }
 78  
 79          if (!isValidXForwardedHost(xForwardedHost)) {
 80              xForwardedHost = request.getHeader(X_FORWARDED_SERVER);
 81  
 82              // If the request has been through multiple reverse proxies,
 83              // We need to return the original Host that the client used
 84              if (xForwardedHost != null) {
 85                  xForwardedHost = xForwardedHost.split(",")[0];
 86              }
 87  
 88              if (!isValidXForwardedHost(xForwardedHost)) {
 89                  xForwardedHost = request.getHeader(X_FORWARDED_FOR);
 90  
 91                  // If the request has been through multiple reverse proxies,
 92                  // We need to return the original Host that the client used
 93                  if (xForwardedHost != null) {
 94                      xForwardedHost = xForwardedHost.split(",")[0];
 95                  }
 96  
 97                  if (!isValidXForwardedHost(xForwardedHost)) {
 98                      throw new RuntimeException("Cannot calculate proxy uri without HTTP headers: " + X_FORWARDED_HOST + ", " + X_FORWARDED_SERVER + ", " + X_FORWARDED_FOR);
 99                  }
100              }
101          }
102  
103          URI proxyHost = new URI("ignored://" + xForwardedHost);
104          String host = proxyHost.getHost();
105          int port = proxyHost.getPort();
106          String scheme = request.getHeader(X_FORWARDED_PROTO);
107          if (StringUtils.isBlank(scheme)) {
108              scheme = request.getHeader(X_FORWARDED_SCHEME);
109              if (StringUtils.isBlank(scheme)) {
110                  throw new RuntimeException("Scheme not provided");
111              }
112          }
113  
114          return new URI(scheme, null, host, port, urlPathHelper.getContextPath(request), null, null);
115      }
