 43      private static final String X_FORWARDED_HOST = "X-Forwarded-Host";
 44      private static final String X_FORWARDED_FOR = "X-Forwarded-For";
 45      private static final String X_FORWARDED_SCHEME = "X-Forwarded-Scheme";
