 53      public static String getBaseUrl(HttpServletRequest request) {
 54          try {
 55              URI uri;
 56              try {
 57                  uri = calculateProxyUri(request);
 58              } catch (Exception e) {
 59                  LOG.debug("Could not calculate proxy uri: " + e.getMessage());
 60                  uri = calculateNonProxyUri(request);
 61              }
 62  
 63              String baseUrl = uri.toString() + "/";
 64              LOG.debug("Calculated base url to " + baseUrl);
 65              return baseUrl;
 66          } catch (MalformedURLException | URISyntaxException e) {
 67              throw new RuntimeException("Could not calculate base url: " + e.getMessage());
 68          }
 69      }
