250       *
251       * @param s The locale string. Should be formatted as per the documentation in {@link Locale#toString()}.
252       * @return The locale.
253       */
254      public static Locale parseLocale(String s) {
255          if (s == null) {
256              return null;
257          }
258  
259          List<String> elements = new ArrayList<>(Arrays.asList(s.split("_", 3)));
260          while (elements.size() < 3) {
261              elements.add("");
262          }
263          return new Locale(elements.get(0), elements.get(1), elements.get(2));
264      }
