 32  @Controller
 33  @MessageMapping("/coverart")
 34  public class CoverArtWSController {
 35      private static final Logger LOG = LoggerFactory.getLogger(CoverArtWSController.class);
 36  
 37      @Autowired
 38      private SecurityService securityService;
 39      @Autowired
 40      private MediaFileService mediaFileService;
 41      @Autowired
 42      private LastFmService lastFmService;
 43      @Autowired
 44      private MediaFolderService mediaFolderService;
 45      @Autowired
 46      private CoverArtService coverArtService;
 47  
 48      @MessageMapping("/search")
 49      @SendToUser(broadcast = false)
 50      public List<LastFmCoverArt> searchCoverArt(CoverArtSearchRequest req) {
 51          return lastFmService.searchCoverArt(req.getArtist(), req.getAlbum());
 52      }
 53  
 54      /**
 55       * Downloads and saves the cover art at the given URL.
 56       *
 57       * @return The error string if something goes wrong, <code>"OK"</code> otherwise.
 58       */
 59      @MessageMapping("/set")
 60      @SendToUser(broadcast = false)
 61      public String setCoverArtImage(CoverArtSetRequest req) {
 62          try {
 63              MediaFile mediaFile = mediaFileService.getMediaFile(req.getId());
 64              saveCoverArt(mediaFile, req.getUrl());
 65              return "OK";
 66          } catch (Exception e) {
 67              LOG.warn("Failed to save cover art for media file {}", req.getId(), e);
 68              return e.toString();
 69          }
 70      }
 71  
 72      private void saveCoverArt(MediaFile dir, String url) throws Exception {
 73          RequestConfig requestConfig = RequestConfig.custom()
 74                  .setConnectTimeout(20 * 1000) // 20 seconds
 75                  .setSocketTimeout(20 * 1000) // 20 seconds
 76                  .build();
 77          HttpGet method = new HttpGet(url);
 78          method.setConfig(requestConfig);
 79  
 80          // Attempt to resolve proper suffix.
 81          String suffix = "jpg";
 82          if (url.toLowerCase().endsWith(".gif")) {
 83              suffix = "gif";
 84          } else if (url.toLowerCase().endsWith(".png")) {
 85              suffix = "png";
 86          }
 87  
 88          // Check permissions.
 89          MusicFolder folder = mediaFolderService.getMusicFolderById(dir.getFolderId());
 90          Path fullPath = dir.getFullPath(folder.getPath());
 91          Path newCoverFile = fullPath.resolve("cover." + suffix);
 92          if (!securityService.isWriteAllowed(folder.getPath().relativize(newCoverFile), folder)) {
 93              throw new SecurityException("Permission denied: " + StringEscapeUtils.escapeHtml(newCoverFile.toString()));
 94          }
 95  
 96          try (CloseableHttpClient client = HttpClients.createDefault();
 97                  CloseableHttpResponse response = client.execute(method);
 98                  InputStream input = response.getEntity().getContent()) {
 99  
100              // If file exists, create a backup.
101              backup(newCoverFile, fullPath.resolve("cover." + suffix + ".backup"));
102  
103              // Write file.
104              Files.copy(input, newCoverFile, StandardCopyOption.REPLACE_EXISTING);
105          }
106  
107          coverArtService.upsert(EntityType.MEDIA_FILE, dir.getId(), folder.getPath().relativize(newCoverFile).toString(), dir.getFolderId(), true);
108      }
109  
110      private void backup(Path newCoverFile, Path backup) {
111          if (Files.exists(newCoverFile)) {
112              try {
113                  Files.move(newCoverFile, backup, StandardCopyOption.REPLACE_EXISTING);
114                  LOG.info("Backed up old image file to {}", backup);
115              } catch (IOException e) {
116                  LOG.warn("Failed to create image file backup {}", backup, e);
117              }
118          }
119      }
120  
121      public void setSecurityService(SecurityService securityService) {
122          this.securityService = securityService;
123      }
124  
125      public void setMediaFileService(MediaFileService mediaFileService) {
126          this.mediaFileService = mediaFileService;
127      }

