 55  /**
 56   * Controller which receives uploaded avatar images.
 57   *
 58   * @author Sindre Mehus
 59   */
 60  @Controller
 61  @RequestMapping("/avatarUpload")
 62  public class AvatarUploadController {
 63  
 64      private static final Logger LOG = LoggerFactory.getLogger(AvatarUploadController.class);
 65      private static final int MAX_AVATAR_SIZE = 64;
 66  
 67      @Autowired
 68      private SettingsService settingsService;
 69      @Autowired
 70      private SecurityService securityService;
 71  
 72      @PostMapping
 73      protected ModelAndView handleRequestInternal(HttpServletRequest request) throws Exception {
 74  
 75          String username = securityService.getCurrentUsername(request);
 76  
 77          // Check that we have a file upload request.
 78          if (!ServletFileUpload.isMultipartContent(request)) {
 79              throw new Exception("Illegal request.");
 80          }
 81  
 82          Map<String, Object> map = new HashMap<String, Object>();
 83          FileItemFactory factory = new DiskFileItemFactory();
 84          ServletFileUpload upload = new ServletFileUpload(factory);
 85          List<FileItem> items = upload.parseRequest(request);
 86  
 87          // Look for file items.
 88          for (FileItem item : items) {
 89              if (!item.isFormField()) {
 90                  String fileName = item.getName();
 91                  byte[] data = item.get();
 92  
 93                  if (StringUtils.isNotBlank(fileName) && data.length > 0) {
 94                      createAvatar(fileName, data, username, map);
 95                  } else {
 96                      map.put("error", new Exception("Missing file."));
 97                      LOG.warn("Failed to upload personal image. No file specified.");
 98                  }
 99                  break;
100              }
101          }
102  
103          map.put("username", username);
104          map.put("avatar", settingsService.getCustomAvatar(username));
105          return new ModelAndView("avatarUploadResult", "model", map);
106      }
107  
108      private void createAvatar(String fileName, byte[] data, String username, Map<String, Object> map) {
109  
110          BufferedImage image;
111          try {
112              image = ImageIO.read(new ByteArrayInputStream(data));
113              if (image == null) {
114                  throw new IOException("Failed to decode incoming image: " + fileName + " (" + data.length + " bytes).");
115              }
116              int width = image.getWidth();
117              int height = image.getHeight();
118              String mimeType = StringUtil.getMimeType(FilenameUtils.getExtension(fileName));
119              Path folder = SettingsService.getAirsonicHome().resolve("avatars").resolve(username);
120              Files.createDirectories(folder);
121              Path fileOnDisk = folder.resolve(fileName + "." + StringUtils.substringAfter(mimeType, "/"));
122              // Scale down image if necessary.
123              if (width > MAX_AVATAR_SIZE || height > MAX_AVATAR_SIZE) {
124                  double scaleFactor = MAX_AVATAR_SIZE / (double)Math.max(width, height);
125                  height = (int) (height * scaleFactor);
126                  width = (int) (width * scaleFactor);
127                  image = CoverArtController.scale(image, width, height);
128                  mimeType = StringUtil.getMimeType("jpeg");
129                  fileOnDisk = folder.resolve(fileName + ".jpeg");
130                  ImageIO.write(image, "jpeg", fileOnDisk.toFile());
131  
132                  map.put("resized", true);
133              } else {
134                  Files.copy(new ByteArrayInputStream(data), fileOnDisk, StandardCopyOption.REPLACE_EXISTING);
135              }
136              Avatar avatar = new Avatar(0, fileName, Instant.now(), mimeType, width, height, fileOnDisk);
137              settingsService.setCustomAvatar(avatar, username);
138              LOG.info("Created avatar '{}' ({} bytes) for user {}", fileName, FileUtil.size(fileOnDisk), username);
139  
140          } catch (IOException x) {
141              LOG.warn("Failed to upload personal image", x);
142              map.put("error", x);
143          }
144      }
145  
