122      @GetMapping("/hls.m3u8")
123      public void handleHlsRequest(Authentication authentication,
124              @RequestParam Integer id,
125              HttpServletRequest request,
126              HttpServletResponse response) throws Exception {
127          MediaFile mediaFile = mediaFileService.getMediaFile(id);
128          Player player = playerService.getPlayer(request, response);
129          String username = player.getUsername();
130  
131          if (mediaFile == null || mediaFile.isDirectory()) {
132              response.sendError(HttpServletResponse.SC_NOT_FOUND, "Media file not found or incorrect type: " + id);
133              return;
134          }
135  
136          if (!(authentication instanceof JWTAuthenticationToken)
137                  && !securityService.isFolderAccessAllowed(mediaFile, username)) {
138              throw new AccessDeniedException("Access to file " + mediaFile.getId() + " is forbidden for user " + username);
139          }
140  
141          Double duration = mediaFile.getDuration();
142          if (duration == null || duration < 0.0001) {
143              response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Unknown duration for media file: " + id);
144              return;
145          }
146  
147          response.setContentType("application/x-mpegurl");
148          response.setCharacterEncoding(StringUtil.ENCODING_UTF8);
149          response.setHeader("Access-Control-Allow-Origin", "*");
150          List<Pair<Integer, Dimension>> bitRates = parseBitRates(request).stream()
151                  .map(b -> b.getRight() != null ? b
152                          : Pair.of(b.getLeft(), TranscodingService.getSuitableVideoSize(mediaFile.getWidth(),
153                                  mediaFile.getHeight(), b.getLeft())))
154                  .collect(Collectors.toList());
155          if (bitRates.isEmpty())
156              bitRates = Collections.singletonList(
157                      Pair.of(VideoPlayerController.DEFAULT_BIT_RATE, TranscodingService.getSuitableVideoSize(
158                              mediaFile.getWidth(), mediaFile.getHeight(), VideoPlayerController.DEFAULT_BIT_RATE)));
159  
160          String requestWithoutContextPath = request.getRequestURI().substring(request.getContextPath().length() + 1);
161          UriComponentsBuilder prefix = UriComponentsBuilder.fromUriString(StringUtils.removeEndIgnoreCase(requestWithoutContextPath, "/hls.m3u8")); // ext/hls or hls
162          String basePath = NetworkService.getBaseUrl(request);
163          PrintWriter writer = response.getWriter();
164          if (bitRates.size() > 1) {
165              generateVariantPlaylist(authentication, basePath, prefix, id, player, bitRates, writer);
166          } else {
167              generateNormalPlaylist(authentication, basePath, prefix, id, player, bitRates.get(0), Math.round(duration), writer);
168          }
169  
170          return;
171      }

