 81          String username = securityService.getCurrentUsername(request);
 82          UserSettings userSettings = settingsService.getUserSettings(username);
 83  
 84          // When was settings last changed?
 85          lastModified = Math.max(lastModified, settingsService.getSettingsChanged());
