 91                  .filter(f -> f.getId().equals(userSettings.getSelectedMusicFolderId()))
 92                  .findAny().orElse(null);
 93          if (selectedMusicFolder != null) {
 94              Path file = selectedMusicFolder.getPath();
 95              lastModified = Math.max(lastModified, FileUtil.lastModified(file).toEpochMilli());
 96          } else {
 97              for (MusicFolder musicFolder : allMusicFolders) {
 98                  Path file = musicFolder.getPath();
 99                  lastModified = Math.max(lastModified, FileUtil.lastModified(file).toEpochMilli());
100              }
101          }
102  
103          // When was music folder table last changed?
104          for (MusicFolder musicFolder : allMusicFolders) {
105              lastModified = Math.max(lastModified, musicFolder.getChanged().toEpochMilli());
106          }
107  
108          // When was internet radio table last changed?
109          for (InternetRadio internetRadio : settingsService.getAllInternetRadios()) {
110              lastModified = Math.max(lastModified, internetRadio.getChanged().toEpochMilli());
111          }
112  
113          // When was user settings last changed?
114          lastModified = Math.max(lastModified, userSettings.getChanged().toEpochMilli());
115  
116          return lastModified;
