 33  public class TransferStatus {
 34  
 35      private static final int HISTORY_LENGTH = 200;
 36      private static final long SAMPLE_INTERVAL_MILLIS = 5000;
 37  
 38      private final UUID id = UUID.randomUUID();
 39      private final Player player;
 40      private Path externalFile;
 41      private MediaFile mediaFile;
 42      private final AtomicLong bytesTransferred = new AtomicLong();
 43      private final AtomicLong bytesSkipped = new AtomicLong();
 44      private final AtomicLong bytesTotal = new AtomicLong();
 45      private final SampleHistory history = new SampleHistory();
 46      private volatile boolean terminated;
 47      private volatile boolean active = true;
 48  
 49      public TransferStatus(Player player) {
 50          this.player = player;
 51      }
