 57      /**
 58       * Return the number of bytes transferred.
 59       *
 60       * @return The number of bytes transferred.
 61       */
 62      public long getBytesTransferred() {
 63          return bytesTransferred.get();
 64      }
 65  
 66      /**
 67       * Adds the given byte count to the total number of bytes transferred.
 68       *
 69       * @param byteCount The byte count.
 70       */
 71      public void addBytesTransferred(long byteCount) {
 72          bytesTransferred.addAndGet(byteCount);
 73          createSample(false);
 74      }
 75  
 76      /**
 77       * Sets the number of bytes transferred.
 78       *
 79       * @param bytesTransferred The number of bytes transferred.
 80       */
 81      public void setBytesTransferred(long bytesTransferred) {
 82          this.bytesTransferred.set(bytesTransferred);
 83          createSample(false);
 84      }
 85  
 86      private synchronized void createSample(boolean force) {
 87          long now = System.currentTimeMillis();
 88  
 89          if (history.isEmpty()) {
 90              history.add(new Sample(bytesTransferred.get(), now));
 91          } else {
 92              Sample lastSample = history.getLast();
 93              if (force || now - lastSample.getTimestamp() > TransferStatus.SAMPLE_INTERVAL_MILLIS) {
 94                  history.add(new Sample(bytesTransferred.get(), now));
 95              }
 96          }
 97      }
 98  
 99      /**
100       * Returns the number of milliseconds since the transfer status was last updated.
101       *
102       * @return Number of milliseconds, or <code>0</code> if never updated.
103       */
104      public long getMillisSinceLastUpdate() {
105          if (history.isEmpty()) {
