 34  /**
 35   * This filter is executed very early in the filter chain. It verifies that
 36   * the Airsonic home directory (c:\airsonic or /var/airsonic) exists and
 37   * is writable. If not, a proper error message is given to the user.
 38   * <p/>
 39   * (The Airsonic home directory is usually created automatically, but a common
 40   * problem on Linux is that the Tomcat user does not have the necessary
 41   * privileges).
 42   *
 43   * @author Sindre Mehus
 44   */
 45  public class BootstrapVerificationFilter implements Filter {
 46  
 47      private static final Logger LOG = LoggerFactory.getLogger(BootstrapVerificationFilter.class);
 48      private boolean airsonicHomeVerified = false;
 49      private final AtomicBoolean serverInfoLogged = new AtomicBoolean();
 50  
 51      public void doFilter(ServletRequest req, ServletResponse res, FilterChain chain)
 52              throws IOException, ServletException {
 53  
 54          // Already verified?
 55          if (airsonicHomeVerified) {
 56              chain.doFilter(req, res);
 57              return;
 58          }
 59  
 60          Path home = SettingsService.getAirsonicHome();
 61          if (!directoryExists(home)) {
 62              error(res, "<p>The directory <b>" + home + "</b> does not exist. Please create it and make it writable, " +
 63                         "then restart the servlet container.</p>" +
 64                         "<p>(You can override the directory location by specifying -Dairsonic.home=... when " +
 65                         "starting the servlet container.)</p>");
 66  
 67          } else if (!directoryWritable(home)) {
 68              error(res, "<p>The directory <b>" + home + "</b> is not writable. Please change file permissions, " +
 69                         "then restart the servlet container.</p>" +
 70                         "<p>(You can override the directory location by specifying -Dairsonic.home=... when " +
 71                         "starting the servlet container.)</p>");
 72  
 73          } else {
 74              airsonicHomeVerified = true;
 75              logServerInfo(req);
 76              chain.doFilter(req, res);
 77          }
 78      }
 79  
 80      private void logServerInfo(ServletRequest req) {
 81          if (!serverInfoLogged.getAndSet(true) && req instanceof HttpServletRequest) {
 82              String serverInfo = ((HttpServletRequest) req).getSession().getServletContext().getServerInfo();
 83              LOG.info("Servlet container: " + serverInfo);
 84          }
 85      }
 86  
 87      private boolean directoryExists(Path dir) {
 88          return Files.exists(dir) && Files.isDirectory(dir);
 89      }
 90  
 91      private boolean directoryWritable(Path dir) {
 92          try {
 93              Path tempFile = Files.createTempFile(dir, "test", null);
 94              return Files.exists(tempFile) && Files.deleteIfExists(tempFile);
 95          } catch (Exception x) {
 96              return false;
 97          }
 98      }
 99  
100      private void error(ServletResponse res, String error) throws IOException {
101          ServletOutputStream out = res.getOutputStream();
102          out.println("<html>" +
103                      "<head><title>Airsonic Error</title></head>" +
104                      "<body>" +
105                      "<h2>Airsonic Error</h2>" +
106                      error +
107                      "</body>" +
108                      "</html>");
109      }
110  
111      public void init(FilterConfig filterConfig) {
112      }
113  
114      public void destroy() {
115      }
116  }

