 49  
 50      /**
 51       * Returns a map from music indexes to sorted lists of artists that are direct children of the given music folders.
 52       *
 53       * @param folders The music folders.
 54       * @param refresh Whether to look for updates by checking the last-modified timestamp of the music folders.
 55       * @return A map from music indexes to sets of artists that are direct children of this music file.
 56       */
 57      public SortedMap<MusicIndex, List<MusicIndex.SortableArtistWithMediaFiles>> getIndexedArtists(List<MusicFolder> folders, boolean refresh) {
 58          List<MusicIndex.SortableArtistWithMediaFiles> artists = createSortableArtists(folders, refresh);
 59          return sortArtists(artists);
 60      }
 61  
 62      public SortedMap<MusicIndex, List<MusicIndex.SortableArtistWithArtist>> getIndexedArtists(List<Artist> artists) {
 63          List<MusicIndex.SortableArtistWithArtist> sortableArtists = createSortableArtists(artists);
 64          return sortArtists(sortableArtists);
 65      }
 66  
 67      public MusicFolderContent getMusicFolderContent(List<MusicFolder> musicFoldersToUse, boolean refresh) {
 68          SortedMap<MusicIndex, List<MusicIndex.SortableArtistWithMediaFiles>> indexedArtists = getIndexedArtists(musicFoldersToUse, refresh);
 69          List<MediaFile> singleSongs = getSingleSongs(musicFoldersToUse, refresh);
 70          return new MusicFolderContent(indexedArtists, singleSongs);
 71      }
 72  
 73      private List<MediaFile> getSingleSongs(List<MusicFolder> folders, boolean refresh) {
 74          return folders.stream().flatMap(f -> mediaFileService
 75                  .getChildrenOf(mediaFileService.getMediaFile(Paths.get(""), f, !refresh), true, false, true, !refresh)
 76                  .stream()).collect(toList());
 77      }
 78  
 79      public List<MediaFile> getShortcuts(List<MusicFolder> musicFoldersToUse) {
 80          return Stream.of(settingsService.getShortcutsAsArray())
 81                  .flatMap(shortcut -> musicFoldersToUse.parallelStream()
 82                          .map(musicFolder -> Pair.of(Paths.get(shortcut), musicFolder)))
 83                  .map(pair -> mediaFileService.getMediaFile(pair.getLeft(), pair.getRight(), true))
 84                  .filter(Objects::nonNull)
 85                  .collect(Collectors.toList());
 86      }
