 88      private <T extends SortableArtist> SortedMap<MusicIndex, List<T>> sortArtists(List<T> artists) {
 89          List<MusicIndex> indexes = createIndexesFromExpression(settingsService.getIndexString());
 90          Comparator<MusicIndex> indexComparator = new MusicIndexComparator(indexes);
 91  
 92          SortedMap<MusicIndex, List<T>> result = new TreeMap<MusicIndex, List<T>>(indexComparator);
 93  
 94          for (T artist : artists) {
 95              MusicIndex index = getIndex(artist, indexes);
 96              List<T> artistSet = result.computeIfAbsent(index, k -> new ArrayList<T>());
 97              artistSet.add(artist);
 98          }
 99  
100          for (List<T> artistList : result.values()) {
101              Collections.sort(artistList);
102          }
103  
104          return result;
105      }
