107      /**
108       * Creates a new instance by parsing the given expression.  The expression consists of an index name, followed by
109       * an optional list of one-character prefixes. For example:<p/>
110       * <p/>
111       * The expression <em>"A"</em> will create the index <em>"A" -&gt; ["A"]</em><br/>
112       * The expression <em>"The"</em> will create the index <em>"The" -&gt; ["The"]</em><br/>
113       * The expression <em>"A(A&Aring;&AElig;)"</em> will create the index <em>"A" -&gt; ["A", "&Aring;", "&AElig;"]</em><br/>
114       * The expression <em>"X-Z(XYZ)"</em> will create the index <em>"X-Z" -&gt; ["X", "Y", "Z"]</em>
115       *
116       * @param expr The expression to parse.
117       * @return A new instance.
118       */
119      protected MusicIndex createIndexFromExpression(String expr) {
