121          if (separatorIndex == -1) {
122  
123              MusicIndex index = new MusicIndex(expr);
124              index.addPrefix(expr);
125              return index;
126          }
127  
128          MusicIndex index = new MusicIndex(expr.substring(0, separatorIndex));
