100          User user = getUserByName(username, caseSensitive);
101          if (user == null) {
102              throw new UsernameNotFoundException("User \"" + username + "\" was not found.");
103          }
104  
105          List<GrantedAuthority> authorities = getGrantedAuthorities(user);
