117      public boolean updateCredentials(UserCredential oldCreds, UserCredential newCreds, String comment,
118              boolean reencodePlaintextNewCreds) {
119          if (!StringUtils.equals(newCreds.getEncoder(), oldCreds.getEncoder()) || reencodePlaintextNewCreds) {
120              if (reencodePlaintextNewCreds) {
121                  newCreds.setCredential(GlobalSecurityConfig.ENCODERS.get(newCreds.getEncoder()).encode(newCreds.getCredential()));
122              } else if (GlobalSecurityConfig.DECODABLE_ENCODERS.contains(oldCreds.getEncoder())) {
123                  try {
124                      // decode using original creds decoder
125                      PasswordDecoder decoder = (PasswordDecoder) GlobalSecurityConfig.ENCODERS.get(oldCreds.getEncoder());
126                      newCreds.setCredential(decoder.decode(oldCreds.getCredential()));
127                      // reencode
128                      newCreds.setCredential(GlobalSecurityConfig.ENCODERS.get(newCreds.getEncoder()).encode(newCreds.getCredential()));
129                  } catch (Exception e) {
130                      LOG.warn("Could not update credentials for user {}", oldCreds.getUsername(), e);
131                      // Do not try and save it
132                      return false;
133                  }
134              }
135          }
136  
137          if (!newCreds.equals(oldCreds)) {
138              newCreds.setComment(comment);
139              newCreds.setUpdated(Instant.now());
140  
141              return userDao.updateCredential(oldCreds, newCreds);
142          }
143  
144          return true;
145      }
146  
147      public boolean createCredential(UserCredential newCreds) {
148          newCreds.setCredential(GlobalSecurityConfig.ENCODERS.get(newCreds.getEncoder()).encode(newCreds.getCredential()));
149          return userDao.createCredential(newCreds);
150      }
