 97      /**
 98       * Sets the list of active transcodings for the given player.
 99       *
100       * @param player         The player.
101       * @param transcodingIds ID's of the active transcodings.
102       */
103      public void setTranscodingsForPlayer(Player player, int[] transcodingIds) {
104          transcodingDao.setTranscodingsForPlayer(player.getId(), transcodingIds);
105      }
106  
107      /**
108       * Sets the list of active transcodings for the given player.
109       *
110       * @param player       The player.
111       * @param transcodings The active transcodings.
112       */
113      public void setTranscodingsForPlayer(Player player, List<Transcoding> transcodings) {
114          int[] transcodingIds = new int[transcodings.size()];
115          for (int i = 0; i < transcodingIds.length; i++) {
116              transcodingIds[i] = transcodings.get(i).getId();
117          }
118          setTranscodingsForPlayer(player, transcodingIds);
119      }
120  
121  
122      /**
123       * Creates a new transcoding.
124       *
125       * @param transcoding The transcoding to create.
126       */
127      public void createTranscoding(Transcoding transcoding) {
128          transcodingDao.createTranscoding(transcoding);
129  
130          // Activate this transcoding for all players?
131          if (transcoding.isDefaultActive()) {
132              playerService.getAllPlayers().parallelStream().filter(Objects::nonNull).forEach(player -> {
133                  List<Transcoding> transcodings = getTranscodingsForPlayer(player);
134                  transcodings.add(transcoding);
135                  setTranscodingsForPlayer(player, transcodings);
136              });
137          }
138      }
