23  
24  public abstract class PlaylistImportHandler implements Ordered {
25      @Autowired
26      MediaFileService mediaFileService;
27  
28      @Autowired
29      SettingsService settingsService;
30  
31      abstract public boolean canHandle(Class<? extends SpecificPlaylist> playlistClass);
32  
33      abstract public Pair<List<MediaFile>, List<String>> handle(SpecificPlaylist inputSpecificPlaylist, Path location);
34  
35      List<MediaFile> getMediaFiles(String pathInPlaylist) {
36          if (StringUtils.isNotBlank(pathInPlaylist)) {
37              Path path = Paths.get(pathInPlaylist);
38              if (path.isAbsolute()) {
39                  // there's only one path to look up
40                  MediaFile m = mediaFileService.getMediaFile(path);
41                  if (m != null) {
42                      return singletonList(m);
43                  }
44              } else {
45                  // need to resolve the root
46                  List<MediaFile> possibles = new ArrayList<>();
47  
48                  // look relative to playlist folder first
49                  Path playlistFolder = Optional.ofNullable(settingsService.getPlaylistFolder()).map(Paths::get).orElse(null);
50                  if (playlistFolder != null) {
51                      Path resolvedFile = playlistFolder.resolve(path).normalize();
52                      MediaFile mediaFile = mediaFileService.getMediaFile(resolvedFile);
53                      if (mediaFile != null) {
54                          possibles.add(mediaFile);
55                      }
56                  }
57  
58                  // look relative to all music folders
59                  possibles.addAll(mediaFileService.getMediaFilesByRelativePath(path).stream()
60                          .filter(m -> !EnumSet.of(MediaType.DIRECTORY, MediaType.ALBUM).contains(m.getMediaType()))
61                          .collect(toList()));
62  
63                  // look relative to home
64                  Path resolvedFile = Paths.get(".").toAbsolutePath().resolve(path).normalize();
65                  MediaFile mediaFile = mediaFileService.getMediaFile(resolvedFile);
66                  if (mediaFile != null) {
67                      possibles.add(mediaFile);
68                  }
69  
70                  return possibles;
71              }
72          }
73  
74          return emptyList();
75      }
76  }

