 71          try (Stream<Path> walk = Files.walk(fileOrFolder)) {
 72              walk.sorted(Comparator.reverseOrder())
 73                  .forEach(uncheckConsumer(Files::deleteIfExists));
 74  
 75              return true;
 76          } catch (NoSuchFileException e) {
 77              LOG.debug("Could not delete file/folder {}", fileOrFolder, e);
 78              return false;
