 3  import org.slf4j.Logger;
 4  import org.slf4j.LoggerFactory;
 5  import org.springframework.boot.WebApplicationType;
 6  import org.springframework.boot.autoconfigure.SpringBootApplication;
 7  import org.springframework.boot.autoconfigure.jmx.JmxAutoConfiguration;
 8  import org.springframework.boot.autoconfigure.web.servlet.MultipartAutoConfiguration;
 9  import org.springframework.boot.builder.SpringApplicationBuilder;
10  import org.springframework.boot.web.server.WebServerFactoryCustomizer;
11  import org.springframework.boot.web.servlet.server.ConfigurableServletWebServerFactory;
12  import org.springframework.boot.web.servlet.support.SpringBootServletInitializer;
13  import org.springframework.context.annotation.AdviceMode;
14  import org.springframework.transaction.annotation.EnableTransactionManagement;
15  import org.springframework.util.ReflectionUtils;
16  
17  import java.lang.reflect.Method;
18  
19  @SpringBootApplication(exclude = {
20      JmxAutoConfiguration.class,
21      MultipartAutoConfiguration.class // TODO: update to use spring boot builtin multipart support
22  })
23  @EnableTransactionManagement(mode = AdviceMode.ASPECTJ)
24  public class Application extends SpringBootServletInitializer implements WebServerFactoryCustomizer<ConfigurableServletWebServerFactory> {
25  
26      private static final Logger LOG = LoggerFactory.getLogger(Application.class);
27  
28      private static SpringApplicationBuilder doConfigure(SpringApplicationBuilder application) {
29          // Customize the application or call application.sources(...) to add sources
30          // Since our example is itself a @Configuration class (via @SpringBootApplication)
31          // we actually don't need to override this method.
32          return application.sources(Application.class).web(WebApplicationType.SERVLET);
33      }
34  
35      @Override
36      protected SpringApplicationBuilder configure(SpringApplicationBuilder application) {
37          return doConfigure(application);
38      }
39  
40      @Override
41      public void customize(ConfigurableServletWebServerFactory container) {
42          LOG.trace("Servlet container is {}", container.getClass().getCanonicalName());
43          // Yes, there is a good reason we do this.
44          // We cannot count on the tomcat classes being on the classpath which will
45          // happen if the war is deployed to another app server like Jetty. So, we
46          // ensure this class does not have any direct dependencies on any Tomcat
47          // specific classes.
48          try {
49              Class<?> tomcatESCF = Class.forName("org.springframework.boot.web.embedded.tomcat.TomcatServletWebServerFactory");
50              if (tomcatESCF.isInstance(container)) {
51                  LOG.info("Detected Tomcat web server");
52                  LOG.debug("Attempting to optimize tomcat");
53                  Object tomcatESCFInstance = tomcatESCF.cast(container);
54                  Class<?> tomcatApplicationClass = Class.forName("org.airsonic.player.TomcatApplication");
55                  Method configure = ReflectionUtils.findMethod(tomcatApplicationClass, "configure", tomcatESCF);
56                  configure.invoke(null, tomcatESCFInstance);
57                  LOG.debug("Tomcat optimizations complete");
58              } else {
59                  LOG.debug("Skipping tomcat optimization as we are not running on tomcat");
60              }
61          } catch (NoClassDefFoundError | ClassNotFoundException e) {
62              LOG.debug("No tomcat classes found");
63          } catch (Exception e) {
64              LOG.warn("An error happened while trying to optimize tomcat", e);
65          }
66      }
67  
68      public static void main(String[] args) {
69          SpringApplicationBuilder builder = new SpringApplicationBuilder();
70          doConfigure(builder).run(args);
71      }
72  
73  }

