 84      /**
 85       * Returns the player associated with the given HTTP request.  If no such player exists, a new
 86       * one is created.
 87       *
 88       * @param request              The HTTP request.
 89       * @param response             The HTTP response.
 90       * @param remoteControlEnabled Whether this method should return a remote-controlled player.
 91       * @param isStreamRequest      Whether the HTTP request is a request for streaming data.
 92       * @return The player associated with the given HTTP request.
 93       */
 94      public synchronized Player getPlayer(HttpServletRequest request, HttpServletResponse response,
 95              Integer playerId, boolean remoteControlEnabled, boolean isStreamRequest) throws Exception {
 96  
 97          Player player = getPlayerById(playerId);
 98  
 99          // Find by 'player' request parameter.
100          if (player == null) {
101              player = getPlayerById(ServletRequestUtils.getIntParameter(request, "player"));
102          }
103  
104          // Find in session context.
105          if (player == null && remoteControlEnabled) {
106              playerId = (Integer) request.getSession().getAttribute("player");
107              if (playerId != null) {
108                  player = getPlayerById(playerId);
109              }
110          }
111  
112          // Find by cookie.
113          String username = securityService.getCurrentUsername(request);
114          if (player == null && remoteControlEnabled) {
115              player = getPlayerById(getPlayerIdFromCookie(request, username));
116          }
117  
118          // Make sure we're not hijacking the player of another user.
119          if (player != null && player.getUsername() != null && username != null && !player.getUsername().equals(username)) {
120              player = null;
121          }
122  
123          // Look for player with same IP address and user name.
124          if (player == null) {
125              player = getNonRestPlayerByIpAddressAndUsername(request.getRemoteAddr(), username);
126          }
127  
128          // If no player was found, create it.
129          if (player == null) {
130              player = new Player();
131              player.setLastSeen(Instant.now());
132              populatePlayer(player, username, request, isStreamRequest);
133              createPlayer(player);
134          } else if (populatePlayer(player, username, request, isStreamRequest)) {
135              updatePlayer(player);
136          }
