 95      /**
 96       * Closes the player, releasing all resources. After this the player state is
 97       * {@link State#CLOSED} (unless the current state is {@link State#EOM}).
 98       */
 99      @Override
100      public synchronized void close() {
101          if (state.get() != CLOSED && state.get() != EOM) {
102              setState(CLOSED);
103          }
104  
105          try {
106              line.stop();
107          } catch (Throwable x) {
108              LOG.warn("Failed to stop player: " + x, x);
109          }
